"""Shared dispatch for legacy governance module aliases."""


def _redirect(name: str, target: str) -> None:
    if name == "__main__":
        import runpy

        runpy.run_module(target, run_name="__main__", alter_sys=True)
    else:
        import importlib
        import sys

        sys.modules[name] = importlib.import_module(target)
